insert into activities (id, name, type, tags, ages, cost, location, km, season, duration, description, url, rating, notes, conditions, lat, lng, daypart, added_by, verified) values
  (54, 'Ocean Grove Skatepark (Ocean Grove Bowl)', 'skatepark', '{"bowl","free","bellarine","all-levels"}', '{"kids","teens","adults"}', 'Free', 'Ocean Grove', 40, '{"any"}', '< 1hr', 'Great concrete bowl on Shell Road Reserve next to the Bellarine Aquatic & Sports Centre. Snakes from a 5ft section into a deeper 8ft section — satisfying lines to link. Good day out combined with Ocean Grove beach or a swim at the aquatic centre next door.', 'https://www.google.com/maps?q=-38.266,144.5168', 4, 'Shell Rd Reserve, Ocean Grove. Next to the aquatic centre', '{"dry-ground"}', -38.266, 144.5168, 'day', 'Research', true),
  (55, 'Barwon Heads Skatepark', 'skatepark', '{"bowl","9ft","convic","bellarine","coastal"}', '{"teens","adults"}', 'Free', 'Barwon Heads', 40, '{"any"}', '< 1hr', 'Beautifully designed Convic-built park in the Barwon Heads Community Park. Unique dog bone-shaped bowl — 9ft deep end tapering to a 4ft shallow section. Great for transition skating. Relaxed coastal town vibe. Combine with a walk to the Barwon Heads bluff for stunning views.', 'https://www.google.com/maps?q=-38.2773,144.4927', 4, 'Sheepwash Rd, Barwon Heads. Nice chill spot after a session', '{"dry-ground"}', -38.2773, 144.4927, 'day', 'Research', true),
  (56, 'Leopold Skatepark', 'skatepark', '{"mini-ramp","street","local-favourite","all-levels"}', '{"kids","teens","adults"}', 'Free', 'Leopold / Geelong', 35, '{"any"}', '< 1hr', 'Small park but packs a punch — widely regarded as one of the best mini ramps in the Geelong region. 4ft mini ramp tapering to banks, plus an extended street section with stairs, rails, ledges and boxes. Friendly community of local skaters. Great for learning lip tricks.', 'https://www.google.com/maps?q=-38.1748,144.4638', 4, 'Cnr Bellarine Hwy & Melaluka Rd, Leopold', '{"dry-ground"}', -38.1748, 144.4638, 'day', 'Research', true),
  (57, 'Lara Skatepark', 'skatepark', '{"snake-run","bowl","new","well-designed","geelong"}', '{"kids","teens","adults"}', 'Free', 'Lara', 40, '{"any"}', '< 1hr', 'One of Victoria''s best designed skateparks — opened 2017. Epic snake-run concrete bowl (6ft down to 4ft) plus a solid street section. Great flow and well-maintained. Worth a detour on the way to/from Melbourne.', 'https://www.google.com/maps?q=-38.0189,144.4053', 4, 'Lara township. On the way to Melbourne — great road trip stop', '{"dry-ground"}', -38.0189, 144.4053, 'day', 'Research', true),
  (58, 'Corio Skatepark (Stead Park Bowls)', 'skatepark', '{"bowl","free","beginner-friendly","geelong-north"}', '{"kids","teens"}', 'Free', 'Corio / Geelong North', 38, '{"any"}', '< 1hr', 'Three concrete bowls of different shapes and sizes — no coping, mellow and forgiving. Super welcoming for younger kids and beginners. Paint-tray dish, oblong bowl, and a larger open bowl. Good first-bowl experience for kids.', 'https://www.google.com/maps?q=-38.1166,144.3454', 3, 'Stead Park, Anakie Rd, Corio. Best for young beginners', '{"dry-ground"}', -38.1166, 144.3454, 'day', 'Research', true),
  (59, 'Djila Tjarra Skatepark (North Shore / Norlane)', 'skatepark', '{"deep-bowl","advanced","geelong","two-parks-linked"}', '{"teens","adults"}', 'Free', 'Norlane / Geelong North', 38, '{"any"}', '< 1hr', 'Two skateparks linked together — old and new park connected so you can skate between them. Features a deep bowl that local pros rate as one of the best in the region. Worth hunting out if you''re a more experienced skater looking for something serious.', 'https://www.google.com/maps?q=-38.0938,144.3444', 4, 'North Shore area, Norlane. Deep bowl — locals only feel, but welcoming', '{"dry-ground"}', -38.0938, 144.3444, 'day', 'Research', true),
  (60, 'Point Lonsdale Skatepark (Gas Works)', 'skatepark', '{"street","quarters","rails","bellarine","coastal"}', '{"kids","teens"}', 'Free', 'Point Lonsdale', 50, '{"any"}', '< 1hr', 'Concrete slab skatepark at the iconic Gas Works site in Point Lonsdale. Heaps of quarters, rails and ledges across a large open surface. Nice spot to combine with a trip to the Point Lonsdale lighthouse and blow-hole.', 'https://www.google.com/maps?q=-38.2919,144.6184', 3, 'Gas Works site, Point Lonsdale. Combine with lighthouse walk', '{"dry-ground"}', -38.2919, 144.6184, 'day', 'Research', true),
  (61, 'Inverleigh Skatepark', 'skatepark', '{"free","country","quiet","local-knowledge","hidden-gem"}', '{"kids","teens"}', 'Free', 'Inverleigh', 45, '{"any"}', '< 1hr', 'Country skatepark in the small town of Inverleigh. Quiet and never crowded — classic hidden gem you''d only know about if someone told you. Good stop on a drive through the Barwon Valley.', 'https://www.google.com/maps/search/Inverleigh+Skatepark+Victoria', 3, 'Cnr Hamilton Hwy & East St, Inverleigh', '{"dry-ground"}', -38.1188, 144.0451, 'day', 'Research', true),
  (62, 'Distillery Creek Picnic Area', 'park', '{"picnic","BBQ","birdwatching","nature-walk","bush","ironbark","family"}', '{"all-ages"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr – half-day', 'Beautiful bush picnic area set among tall ironbark trees just behind Aireys Inlet. Two car parks — lower and upper — both with picnic tables and wood-fired BBQs (bring your own wood). Toilets and info board at upper car park. Short 1.5km nature trail loops through the ironbark forest — brilliant birdwatching. Also the trailhead for longer walks to Painkalac Dam and Moggs Creek. Links to MTB trails too. A genuine local gem — quiet and beautiful.', 'https://www.google.com/maps/search/Distillery+Creek+Picnic+Area+Aireys+Inlet', 5, 'Turn off GOR at Bambra Rd just east of Aireys Inlet shops. Follow 2.5km then left on Distillery Creek Rd', '{"dry-ground","warm"}', -38.4659, 144.1077, 'day', 'Research', true),
  (63, 'Sheoak Picnic Area', 'park', '{"picnic","BBQ","waterfalls","rainforest","walk-hub","family"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 35, '{"any"}', 'half-day – full-day', 'The waterfall capital of Victoria — arguably the best picnic base in the whole Otways. Set among giant eucalypts and cool fern gullies, 3.5km behind Lorne. Tables, gas BBQs, toilets, info board. Hub for walks to Henderson Falls (1.5km), Kalimna Falls (4.2km), Phantom Falls (4.3km), Castle Rock lookout, and more. Glow worms visible in the gully at night near the suspension bridge. Check Parks Victoria for any closures before going — some tracks affected by 2026 flood damage.', 'https://www.google.com/maps/search/Sheoak+Picnic+Area+Lorne+Victoria', 5, 'Via Allenvale Rd, Lorne — 3.5km from GOR. Check Parks Vic for closures before visiting', '{"dry-ground","warm"}', -38.5423, 143.9908, 'day', 'Research', true),
  (64, 'Moggs Creek Picnic Area', 'park', '{"picnic","ocean-views","walk","quiet","family"}', '{"all-ages"}', 'Free', 'Aireys Inlet / Fairhaven', 20, '{"any"}', '< 1hr – half-day', 'Peaceful picnic area in Great Otway National Park near Fairhaven. Starting point for the Ocean View Track with stunning views of the Great Ocean Road, Fairhaven beach and the Southern Ocean. Quieter than Distillery Creek. Can be linked by walk to Distillery Creek for a longer adventure.', 'https://www.google.com/maps/search/Moggs+Creek+Picnic+Area+Great+Ocean+Road', 4, 'Just off the GOR between Aireys Inlet and Fairhaven', '{"dry-ground","warm"}', -38.5102, 144.0173, 'day', 'Research', true),
  (65, 'Blanket Leaf Picnic Area', 'park', '{"picnic","fireplace","shelter","tall-trees","family","Erskine-Falls"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 35, '{"any"}', '< 1hr – half-day', 'Lovely picnic area nestled among tall eucalyptus trees in Great Otway National Park. Accessible tables, fireplaces and sheltered areas. Close to Erskine Falls and the Lemonade Creek Walk through fern gullies. Beautiful shaded spot on a hot day — stays cool under the canopy.', 'https://www.google.com/maps/search/Blanket+Leaf+Picnic+Area+Lorne+Victoria', 4, 'Near Erskine Falls Rd, Lorne hinterland', '{"dry-ground","no-fire-ban"}', -38.5487, 143.9752, 'day', 'Research', true),
  (66, 'Anglesea River Picnic Area', 'park', '{"picnic","river","family","dogs-welcome","kangaroos","easy"}', '{"all-ages"}', 'Free', 'Anglesea', 15, '{"any"}', '< 1hr', 'Flat grassy picnic area along the beautiful Anglesea River right in town. Picnic tables, BBQs, shade. Combine with a paddle at Anglesea Paddle Boats next door, a walk along the river trail, or a look for kangaroos at the golf course just up the road. Perfect easy family stop.', 'https://www.google.com/maps/search/Anglesea+River+picnic+area+Victoria', 4, 'Riverbank, Anglesea town centre. Walk distance to everything in Anglesea', '{"warm"}', -38.4062, 144.184, 'day', 'Research', true),
  (67, 'Lake Elizabeth Picnic Area', 'park', '{"picnic","platypus","lake","rainforest","magical","quiet"}', '{"all-ages"}', 'Free', 'Forrest (Otways)', 75, '{"any"}', 'half-day', 'One of Victoria''s most magical spots — a tranquil lake enclosed by tall trees and fern gullies in the Otways hinterland. Mist drifts across the water in the early hours. Picnic tables, toilets, shaded seating. Walk the lake loop trail (easy, ~1hr). Platypus regularly spotted at dawn and dusk — bring patience and binoculars. Note: campground car park closed Jan–Mar 2026 for upgrades.', 'https://www.google.com/maps/search/Lake+Elizabeth+Forrest+Victoria', 5, 'Near Forrest, Otways. Dawn/dusk = best platypus sightings. Check Parks Vic for 2026 car park closure', '{"dry-ground","warm"}', -38.5421, 143.7476, 'day', 'Research', true),
  (68, 'Painkalac Dam Picnic Spot', 'park', '{"picnic","dam","birdwatching","walking","hidden-gem","local-knowledge"}', '{"all-ages"}', 'Free', 'Aireys Inlet (hinterland)', 20, '{"any"}', '< 1hr – half-day', 'Aireys Inlet''s former water supply — now a peaceful public picnic spot. Picnic tables at the dam wall with lovely water views and excellent birdwatching. Possible platypus sighting in the creek below. Access via the walking track from Distillery Creek Picnic Area (~3km each way) or drive in on the Barwon Water access road. Very few people know about this one.', 'https://www.google.com/maps/search/Painkalac+Dam+Aireys+Inlet', 4, 'Access via Distillery Creek Rd. Very quiet — almost nobody comes here', '{"dry-ground","warm"}', -38.4667, 144.0869, 'day', 'Research', true),
  (69, 'Jan Juc Caravan Park', 'camping', '{"local","family-friendly","walking-distance","powered","dogs-seasonal"}', '{"all-ages"}', 'Cheap', 'Jan Juc', 1, '{"any"}', 'overnight', 'Your local caravan park right on Sunset Strip — ideal for visiting friends and family who want to stay close. Powered and unpowered sites, good facilities. Walking distance to the skatepark, rockpools and Jan Juc beach.', 'https://www.google.com/maps/search/Jan+Juc+Caravan+Park', 4, '93 Sunset Strip, Jan Juc. Ph: (03) 5261 2932', '{"dry-ground"}', -38.3589, 144.2991, 'both', 'Research', true),
  (70, 'Torquay Foreshore Caravan Park', 'camping', '{"beachfront","glamping","family","powered","jumping-pillow","dogs-seasonal"}', '{"all-ages"}', 'Moderate', 'Torquay', 5, '{"any"}', 'overnight', 'The only beachfront caravan park in Torquay — right on the Back Beach and Spring Creek. Great range of options: powered/unpowered sites, cabins, glamping tents and pods. Indoor games room, jumping pillow, direct beach access. Dogs welcome seasonally (May–Oct). Book well ahead in summer.', 'https://greatoceanroadparks.com.au/find-a-park/torquay', 5, 'Torquay Back Beach. Book early — fills fast in Jan/Feb', '{"any-weather"}', -38.331, 144.3258, 'both', 'Research', true),
  (71, 'Anglesea Family Caravan Park', 'camping', '{"riverside","family","powered","kangaroos","popular"}', '{"all-ages"}', 'Moderate', 'Anglesea', 15, '{"any"}', 'overnight', 'Beautifully positioned right on the Anglesea River in town. Powered and unpowered sites, cabins. Walking distance to beach, shops and restaurants. Kangaroos often wander through. Very popular — book months ahead for peak season.', 'https://www.google.com/maps/search/Anglesea+Family+Caravan+Park', 5, 'Anglesea River foreshore. One of the best positioned parks on the coast', '{"any-weather"}', -38.4044, 144.18, 'both', 'Research', true),
  (72, 'BIG4 Aireys Inlet Holiday Park', 'camping', '{"powered","family-friendly","near-lighthouse","dogs-seasonal"}', '{"all-ages"}', 'Moderate', 'Aireys Inlet', 18, '{"any"}', 'overnight', 'Well-run family park in Aireys Inlet. Powered sites, cabins, good facilities. Short walk to the Split Point Lighthouse, pub, cafes and beach. Great base for exploring Anglesea and Lorne. Dogs allowed seasonally.', 'https://www.big4.com.au/caravan-parks/vic/great-ocean-road/aireys-inlet-holiday-park', 4, '19-25 Great Ocean Rd, Aireys Inlet', '{"any-weather"}', -38.4558, 144.1029, 'both', 'Research', true),
  (73, 'Lorne Foreshore Caravan Park', 'camping', '{"riverside","glamping","family","central","popular"}', '{"all-ages"}', 'Moderate', 'Lorne', 30, '{"any"}', 'overnight', 'Three campgrounds along the Erskine River right in Lorne town. Steps from the beach, shops, cafes and restaurants. Glamping tents available for a more comfortable experience. One of the most popular parks on the coast — book very early for summer.', 'https://greatoceanroadparks.com.au/find-a-park/lorne', 5, '2 Great Ocean Rd, Lorne. Ph: (03) 5289 1382. Book 6+ months ahead for Jan', '{"any-weather"}', -38.5397, 143.9774, 'both', 'Research', true),
  (74, 'Cumberland River Holiday Park', 'camping', '{"riverside","bush","walks","secluded","family"}', '{"all-ages"}', 'Moderate', 'Cumberland River', 40, '{"any"}', 'overnight', 'Hidden gem between Lorne and Wye River on the Cumberland River. Cabins and campsites in a stunning bush riverside setting. Walks straight into the Otways from camp. Beautiful beach opposite. River has great swimming holes to cool off. Much quieter than Lorne.', 'https://www.google.com/maps/search/Cumberland+River+Holiday+Park+Victoria', 5, '2680 Great Ocean Rd, Cumberland River. Ph: (03) 5289 1790', '{"any-weather"}', -38.5559, 143.9601, 'both', 'Research', true),
  (75, 'Wye River Foreshore Camping', 'camping', '{"beachfront","small-town","foreshore","unpowered","family"}', '{"all-ages"}', 'Cheap', 'Wye River', 48, '{"any"}', 'overnight', 'Foreshore camping in the gorgeous little town of Wye River. Right on the beach — fall asleep to the sound of waves. Unpowered sites, basic facilities. The town itself is tiny and beautiful. Books out very fast — one of the most sought-after spots on the coast.', 'https://www.google.com/maps/search/Wye+River+Foreshore+Camping+Reserve', 5, 'Books out months ahead. Check availability early', '{"dry-ground"}', -38.6085, 143.8781, 'both', 'Research', true),
  (76, 'BIG4 Wye River Holiday Park', 'camping', '{"powered","family","facilities","Wye-River"}', '{"all-ages"}', 'Moderate', 'Wye River', 48, '{"any"}', 'overnight', 'The more facilities-focused option at Wye River. Powered sites, amenities blocks, camp kitchen. Better chance of availability than the foreshore reserve. Still a magical little coastal town to base yourself in.', 'https://www.big4.com.au/caravan-parks/vic/great-ocean-road/wye-river-holiday-park', 4, 'Wye River township', '{"dry-ground"}', -38.6085, 143.8781, 'both', 'Research', true),
  (77, 'Kennett River Family Caravan Park', 'camping', '{"old-school","bush","koala-walk","family","grassy"}', '{"all-ages"}', 'Moderate', 'Kennett River', 55, '{"any"}', 'overnight', 'A beloved old-school park — dirt roads, grassy sites under the gums, lots of space between sites. Right next to the famous Kennett River Koala Walk where koalas are almost guaranteed in the trees. Unpretentious and brilliant.', 'https://www.google.com/maps/search/Kennett+River+Family+Caravan+Park', 5, 'Kennett River, Great Ocean Rd. Koalas in the trees above camp', '{"dry-ground"}', -38.6581, 143.7214, 'both', 'Research', true),
  (78, 'Bimbi Park – Camp under Koalas', 'camping', '{"koalas","bush","campfire","glamping","family","wildlife","Cape-Otway"}', '{"all-ages"}', 'Moderate', 'Cape Otway', 90, '{"any"}', 'overnight', 'Camp under Manna Gum trees absolutely filled with koalas. Family-run park that''s been a favourite for decades. Powered and unpowered sites, cabins, glamping tents, campfire allowed. Camp kitchen, kiosk, laundry. Dark skies — brilliant for stargazing. Close to Cape Otway Lighthouse. One of the most special camps in Victoria.', 'https://www.bimbipark.com.au', 5, '90 Manna Gum Dr, Cape Otway. Book ahead — very popular', '{"clear-sky","no-fire-ban"}', -38.8548, 143.5177, 'both', 'Research', true),
  (79, 'Forrest Caravan Park', 'camping', '{"MTB-base","bush","family","powered","Forrest"}', '{"all-ages"}', 'Cheap', 'Forrest', 75, '{"any"}', 'overnight', 'The perfect base for a Forrest MTB weekend. Right in the heart of Forrest township, walking distance to the trails and the famous Forrest Brewing Company. Powered and unpowered sites. Book ahead for the Otway Odyssey MTB race weekend in February.', 'https://www.google.com/maps/search/Forrest+Caravan+Park+Victoria', 4, '1 Station St, Forrest. Ph: (03) 5236 6272', '{"dry-ground"}', -38.5238, 143.7259, 'both', 'Research', true),
  (80, 'Big Hill Campground', 'camping', '{"bush-camping","free-ish","dogs-ok","quiet","Otways"}', '{"teens","adults"}', 'Cheap', 'Lorne-Deans Marsh Rd', 35, '{"any"}', 'overnight', 'Peaceful bush campground in the Otways. Drop toilets and rainwater tanks. $15.70/night via Parks Victoria — used to be free. Dogs allowed (not in a national park). Can get busy with 4WD riders on weekends. Dark skies — good stargazing. Phone reception is patchy — enjoy the disconnect.', 'https://www.google.com/maps/search/Big+Hill+Campground+Otways+Victoria', 4, 'Intersection of Big Hill Track & Lorne-Deans Marsh Rd. Book via Parks Vic', '{"dry-ground"}', -38.5779, 143.9166, 'both', 'Research', true),
  (81, 'Allenvale Campground', 'camping', '{"walk-in","riverside","tiny","secluded","Lorne"}', '{"teens","adults"}', 'Cheap', 'Behind Lorne', 32, '{"spring","summer","autumn"}', 'overnight', 'Intimate walk-in campground (just 230m from the carpark) on the banks of the St George River. Very small — a handful of sites only. Peaceful and secluded. Great access to Lorne''s waterfall walking tracks. Not suitable for caravans or large rigs.', 'https://www.google.com/maps/search/Allenvale+Campground+Lorne+Victoria', 4, 'Short walk from Allenvale Rd carpark behind Lorne', '{"dry-ground"}', -38.556, 143.971, 'both', 'Research', true),
  (82, 'Jamieson Creek Campground', 'camping', '{"renovated","riverside","tents-caravans","walks","ocean-views"}', '{"all-ages"}', 'Cheap', 'Skenes Creek / Wye River', 55, '{"any"}', 'overnight', 'Newly renovated compact campground near Skenes Creek. Accepts tents, caravans and camper trailers. Panoramic ocean views from camp. Direct access to walking tracks to Wye River and beyond. Peaceful and well-positioned in the Otways hinterland.', 'https://www.google.com/maps/search/Jamieson+Creek+Campground+Victoria', 4, 'Near Skenes Creek. Book via Parks Victoria', '{"dry-ground"}', -38.5959, 143.8577, 'both', 'Research', true),
  (83, 'Lake Elizabeth Campground', 'camping', '{"platypus","glow-worms","forest","basic","MTB-base"}', '{"all-ages"}', 'Cheap', 'Forrest (Otways)', 75, '{"any"}', 'overnight', 'Basic bush camping in the forest right near Lake Elizabeth. Famous for platypus sightings at dawn and dusk, and glow worms at night. Drop toilets, untreated rainwater. No fires. Links directly to Forrest MTB trails. ⚠️ Car park closed Jan–Mar 2026 for upgrades — check Parks Vic before going.', 'https://www.google.com/maps/search/Lake+Elizabeth+Campground+Forrest+Victoria', 5, '~$14.50/night. Check Parks Vic — car park closed until late March 2026', '{"dry-ground"}', -38.5421, 143.7476, 'both', 'Research', true),
  (84, 'Blanket Bay Campground', 'camping', '{"coastal-forest","rockpools","koalas","unpowered","Cape-Otway"}', '{"all-ages"}', 'Cheap', 'Cape Otway', 95, '{"any"}', 'overnight', 'Stunning campground right in the forest on the coastal shores of Cape Otway. 22 unpowered sites for tents, caravans and motorhomes. Sheltered bay perfect for swimming. Rockpools teeming with marine life. Koalas in the trees above. Dark skies, very remote feel. Book via Parks Victoria — popular and fills fast.', 'https://www.google.com/maps/search/Blanket+Bay+Campground+Cape+Otway', 5, 'Blanket Bay Rd, Cape Otway. Book via Parks Vic — especially summer', '{"clear-sky"}', -38.8348, 143.5383, 'both', 'Research', true),
  (85, 'Parker Hill Campground', 'camping', '{"very-basic","bush","remote","Cape-Otway","dark-skies"}', '{"teens","adults"}', 'Cheap', 'Cape Otway', 95, '{"any"}', 'overnight', 'Very basic and beautiful bush camping near Cape Otway. No power, drop toilets only. For those who want true wilderness. Dark skies are exceptional — excellent stargazing. Book via Parks Victoria.', 'https://www.google.com/maps/search/Parker+Hill+Campground+Cape+Otway', 4, 'Parker Hill Track, Cape Otway. Book via Parks Vic', '{"clear-sky"}', -38.8282, 143.543, 'both', 'Research', true),
  (86, 'Milky Way Stargazing – Surf Coast', 'night', '{"stargazing","Milky-Way","free","dark-sky","astrophotography","family"}', '{"all-ages"}', 'Free', 'Bells Beach / Point Addis / Jan Juc', 0, '{"winter","autumn"}', '< 1hr – half-day', 'The Surf Coast sits at a perfect latitude and away from major city light pollution — ideal for naked-eye Milky Way on clear moonless nights. Best local spots: Bells Beach car park (faces south, no artificial light), Point Addis headland, and Jan Juc beach looking south. Best season: autumn–winter when the galactic core is highest. Best conditions: new moon, clear skies, no wind. Use the Stellarium or SkySafari app to identify what you''re seeing. Bring a blanket, red torch (preserves night vision), and hot drinks.', 'https://www.google.com/maps/search/Bells+Beach+Torquay+Victoria', 5, 'New moon = best. Check Weather & Moon Phase apps first. Red torch only to preserve night vision', '{"clear-sky","new-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (87, 'Aurora Australis (Southern Lights) Chase', 'night', '{"aurora","southern-lights","celestial","rare","photography","night"}', '{"all-ages"}', 'Free', 'Jan Juc / Bells Beach / Point Addis', 0, '{"winter","spring"}', '< 1hr', 'The Surf Coast is one of the best mainland spots in Victoria for Aurora Australis sightings. Confirmed sightings from Bells Beach and Torquay — locals report the whole of Torquay came out for a particularly spectacular display in early 2026. Face south with a clear horizon (Bells Beach or Jan Juc beach). Best months: May–August, also September equinox. How to track: subscribe to BoM Space Weather alerts, use SpaceWeatherLive or My Aurora Forecast app, join the Aurora Australis Australia Facebook group for real-time alerts. Camera tip: even a phone camera on night mode will often capture colour the naked eye misses.', 'https://www.sws.bom.gov.au/Aurora', 5, 'Set up aurora alerts on your phone — it happens with only 30min warning. Always face south', '{"clear-sky","low-wind","geomagnetic-storm"}', -38.3682, 144.296, 'night', 'Research', true),
  (88, 'Bioluminescence / Sea Sparkle Watch', 'night', '{"bioluminescence","sea-sparkle","magical","rare","night","beach"}', '{"all-ages"}', 'Free', 'Jan Juc / Lorne / Surf Coast beaches', 0, '{"summer","autumn"}', '< 1hr', 'One of the most magical natural phenomena you can witness locally — and it happens here. Bioluminescent waves (Sea Sparkle / Noctiluca scintillans) light the surf up blue. Confirmed sighting: Surf Coast near Lorne, June 2025. Best conditions: calm warm nights, dark moon, after calm sunny days. Walk through wet sand or disturb the water at the shoreline to trigger the glow. Any south-facing beach works — Jan Juc, Bells Beach, Fairhaven, Lorne. Track sightings on the Bioluminescence Australia Facebook group.', 'https://www.facebook.com/groups/BioluminescenceAustralia', 5, 'Can''t be predicted — join the Bioluminescence Australia FB group for local alerts', '{"calm-sea","new-moon","warm"}', -38.3682, 144.296, 'night', 'Research', true),
  (89, 'Glow Worm Walk – Sheoak / Allenvale', 'night', '{"glow-worms","night-walk","magical","rainforest","family"}', '{"all-ages"}', 'Free', 'Lorne (hinterland)', 32, '{"any"}', '< 1hr', 'After dark, the suspension bridge gully at Sheoak Picnic Area comes alive with glow worms. Tiny bioluminescent larvae of fungus gnats clinging to the moist fern-covered banks. Walk slowly with a red torch only — white light kills the experience. Also visible along the Allenvale track. Combine with a night walk to listen to the forest come alive with frogs and owls. Free, no booking needed — just go after dark.', 'https://www.google.com/maps/search/Sheoak+Picnic+Area+Lorne+Victoria', 5, 'Red torch only! Take it slowly. Wettest months = most glow worms', '{"new-moon"}', -38.5423, 143.9908, 'night', 'Research', true),
  (90, 'Snake Valley Dark Sky Site (Ballarat region)', 'night', '{"dark-sky","official","astronomy","telescope","events","ballarat"}', '{"all-ages"}', 'Free', 'Snake Valley (nr Ballarat)', 100, '{"any"}', 'overnight', 'Official Australian Dark Sky Site — one of the best in Victoria. Run by the Snake Valley Astronomical Association. Monthly club nights open to visitors, astronomy classes, telescope viewing. Moon, nebulae, star clusters, galaxies. About 100km from Jan Juc — worth combining with a Ballarat day trip. Check their website for public event dates before going.', 'https://www.google.com/maps/search/Snake+Valley+Astronomical+Association+Victoria', 4, '825 Linton-Carngham Rd, Snake Valley. Check event calendar — not open every night', '{"clear-sky","new-moon","low-wind"}', -37.457, 143.5688, 'night', 'Research', true),
  (91, 'Whale Watching – Point Addis Headland', 'night', '{"whales","wildlife","seasonal","free","binoculars","clifftop"}', '{"all-ages"}', 'Free', 'Point Addis', 8, '{"winter","spring"}', '< 1hr – half-day', 'Point Addis headland is one of the closest spots to Jan Juc for land-based whale watching. Southern Right Whales, Humpbacks and occasionally Orcas pass close to shore June–October during their annual migration. The high clifftop gives an excellent vantage point — whales sometimes come within metres of the cliffs. Bring binoculars. Best in calm conditions when the sea surface is smooth — blows are easy to spot. Dawn and dusk are best — calmer seas and better light. Also good for spotting dolphins and seabirds year-round.', 'https://www.google.com/maps/search/Point+Addis+Marine+National+Park+Victoria', 5, 'June–October. Face north-west from the headland. Binoculars essential. Dawn/dusk best', '{"calm-sea","clear-sky"}', -38.3975, 144.2534, 'night', 'Research', true),
  (92, 'Whale Watching – Teddy''s Lookout, Lorne', 'night', '{"whales","lookout","scenic","seasonal","free","binoculars"}', '{"all-ages"}', 'Free', 'Lorne', 30, '{"winter","spring"}', '< 1hr', 'Teddy''s Lookout is one of the best whale watching vantage points on the Surf Coast — high above the coast where the St George River meets the sea. Southern Right Whales and Humpbacks pass by June–October. Also one of the most spectacular sunset and moonrise viewpoints on the entire Great Ocean Road. Short walk from the car park. No cost, no booking.', 'https://www.google.com/maps/search/Teddys+Lookout+Lorne+Victoria', 5, 'William St, Lorne. Also brilliant for sunrise/sunset — combine both', '{"calm-sea","clear-sky"}', -38.5403, 143.9796, 'night', 'Research', true),
  (93, 'Sunset at Point Danger / Yellow Bluff', 'night', '{"sunset","clifftop","free","photography","romantic","local"}', '{"all-ages"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr', 'Point Danger and Yellow Bluff are the best local sunset spots — high clifftop lookouts just north of Torquay with sweeping views west along the coast. On a clear evening the sky lights up orange and pink over the ocean. Very easy walk from the Torquay carpark. Bring a drink and a blanket. A genuinely magical spot that locals take for granted.', 'https://www.google.com/maps/search/Point+Danger+Torquay+Victoria', 5, 'Short walk from Torquay Front Beach car park. Face west for the full show', '{"clear-sky","low-wind"}', -38.3556, 144.3124, 'night', 'Research', true),
  (94, 'Sunset at Split Point Lighthouse', 'night', '{"sunset","lighthouse","iconic","photography","Aireys-Inlet"}', '{"all-ages"}', 'Free', 'Aireys Inlet', 18, '{"any"}', '< 1hr', 'The Split Point Lighthouse (from Round the Twist!) on the clifftop at Aireys Inlet is one of the most photogenic sunset spots on the coast. The lighthouse glows warm against a golden sky, with Eagle Rock visible below. Combine with a walk along the clifftop track and dinner at the Aireys Inlet pub afterwards.', 'https://www.google.com/maps/search/Split+Point+Lighthouse+Aireys+Inlet', 5, 'Walk up from the Aireys Inlet carpark. Free to walk the grounds', '{"clear-sky"}', -38.4607, 144.1032, 'night', 'Research', true),
  (95, 'Moonrise Watch – Bells Beach / Jan Juc', 'night', '{"moonrise","full-moon","free","photography","celestial","romantic"}', '{"all-ages"}', 'Free', 'Bells Beach / Jan Juc', 2, '{"any"}', '< 1hr', 'One of the most underrated experiences on the Surf Coast — watching the full moon rise out of the Southern Ocean from Bells Beach or the Jan Juc cliffs. The moon comes up orange and enormous on the eastern horizon, tracking across the ocean. Best from the Bells Beach car park or the clifftop path at Jan Juc looking east/south-east. Check a moon phase calendar and plan around the full moon — it rises at sunset and is visible all night. Bring a tripod for photos if you have one.', 'https://www.google.com/maps/search/Bells+Beach+Torquay+Victoria', 5, 'Use TimeandDate.com or Moon+ app to find exact moonrise time and direction', '{"clear-sky","full-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (96, 'Night Fishing – Jan Juc Creek / Rocks', 'night', '{"fishing","night","local","free","teens","adults","squid"}', '{"teens","adults"}', 'Free', 'Jan Juc', 0, '{"any"}', '< 1hr – half-day', 'Jan Juc has a few good local spots for evening and night fishing. The creek mouth and rock platforms are popular for squid, flathead and salmon after dark. Squid are especially good at night — use a jig and a light source at the water surface. Always check local fishing rules and size limits. Torch, warm layers and a thermos are essential gear.', 'https://www.google.com/maps/search/Jan+Juc+Creek+Victoria', 4, 'Check VFA fishing rules. A fishing licence is required in Victoria for those 18+', '{"low-tide","calm-sea"}', -38.3655, 144.2978, 'night', 'Research', true),
  (97, 'Night Fishing – Torquay Pier / Front Beach', 'night', '{"fishing","night","pier","squid","snapper","family"}', '{"teens","adults"}', 'Free', 'Torquay', 4, '{"any"}', '< 1hr – half-day', 'The Torquay foreshore and pier area are popular after-dark fishing spots. Squid jigging under lights at the pier is productive in the right conditions. Salmon, flathead and snapper also taken from the rocks and beach at night. The Fisherman''s Beach area is a local favourite. A good social activity — often find other anglers happy to share tips.', 'https://www.google.com/maps/search/Torquay+Fishermans+Beach+Victoria', 4, 'Fishing licence required (18+). Best in autumn and winter for squid', '{"high-tide","calm-sea"}', -38.3269, 144.3252, 'night', 'Research', true),
  (100, 'Pub Trivia Night – Surf Coast', 'night', '{"trivia","pub","community","social","family-friendly","fun"}', '{"adults","teens"}', 'Cheap', 'Torquay / Anglesea', 5, '{"any"}', '< 1hr – half-day', 'Several pubs on the Surf Coast run regular trivia nights — a great way to meet the community. The Sands Hotel in Torquay and various Anglesea venues run weekly or monthly trivia. Teams of 4–6, prizes for winners. Check with local venues for current schedules — they change seasonally.', 'https://www.google.com/maps/search/The+Sands+Hotel+Torquay+Victoria', 4, 'Call ahead to confirm trivia nights are running — schedules change seasonally', '{"any-weather"}', -38.329, 144.3245, 'night', 'Research', true),
  (102, 'Backyard Bonfire / Fire Pit Night', 'night', '{"at-home","fire","community","free","cosy","winter","social"}', '{"all-ages"}', 'Free', 'Home / Jan Juc', 0, '{"autumn","winter","spring"}', 'half-day', 'Nothing beats a backyard fire pit on a clear Surf Coast evening. Invite the neighbours. Toasted marshmallows, stories, guitars optional. On a clear night the stars above Jan Juc are brilliant — combine with some naked-eye stargazing. Always check current fire restrictions before lighting (Vic Fire Danger Rating). Use the VicEmergency app or CFA website for daily fire danger ratings.', 'https://www.emergency.vic.gov.au/prepare/know-your-risk/fire-danger-ratings', 5, 'Always check CFA fire danger rating first. Never light a fire on a Total Fire Ban day', '{"no-fire-ban","clear-sky"}', -38.3655, 144.2978, 'night', 'Research', true),
  (103, 'Outdoor Movie Night at Home', 'night', '{"at-home","movies","family","free","projector","fun"}', '{"all-ages"}', 'Free', 'Home / Jan Juc', 0, '{"summer","autumn","spring"}', 'half-day', 'Set up a projector or big screen in the backyard. Hire a projector from a local AV store, or invest in a budget one — they''ve come down hugely in price. String some lights, set up bean bags and blankets. Vote on a film, make themed popcorn. Warm summer evenings on the Surf Coast are perfect for this. Invite neighbours for a community screening.', null, 5, 'Budget projectors from ~$80 on Amazon. Needs a white wall or sheet', '{"warm","dry-trails"}', -38.3655, 144.2978, 'night', 'Research', true),
  (104, 'Meteor Shower Watching', 'night', '{"meteor-shower","celestial","free","seasonal","family","stargazing"}', '{"all-ages"}', 'Free', 'Bells Beach / Point Addis / Jan Juc beach', 2, '{"any"}', '< 1hr', 'Several major meteor showers are visible from the Surf Coast each year. Key annual events: Eta Aquarids (late April–May, peak ~May 6, best in southern hemisphere), Southern Delta Aquarids (late July–August), Orionids (October), Geminids (December). Head to a dark south-facing beach — Bells Beach car park or Jan Juc beach are perfect. Lie flat on a blanket, let eyes adjust for 20 minutes, face away from any lights. No equipment needed — naked eye is best for shooting stars. Use the Meteor Shower app or TimeandDate.com for exact peak dates each year.', 'https://www.timeanddate.com/astronomy/meteor-shower/', 5, 'Eta Aquarids (May) is the best for southern hemisphere — up to 50 meteors/hour at peak', '{"clear-sky","new-moon","low-wind"}', -38.3721, 144.2829, 'night', 'Research', true),
  (105, 'ISS (Space Station) Spotting', 'night', '{"ISS","space-station","celestial","free","family","quick","fun"}', '{"all-ages"}', 'Free', 'Jan Juc / anywhere', 0, '{"any"}', '< 1hr', 'The International Space Station passes over Jan Juc regularly and is easily visible to the naked eye — it looks like a fast-moving, very bright star tracking silently across the sky. Takes about 2–3 minutes to cross the whole sky. Use the NASA Spot the Station website or the ISS Detector app for exact pass times. Set an alert for ''bright passes'' — magnitude -3 or brighter are spectacular. A brilliant quick activity — works from your own backyard.', 'https://spotthestation.nasa.gov', 5, 'Free alerts at spotthestation.nasa.gov — set your location to Torquay. Kids love it', '{"clear-sky","low-wind"}', -38.3655, 144.2978, 'night', 'Research', true),
  (106, 'Planet Watching – Naked Eye Planets', 'night', '{"planets","celestial","free","educational","family","stargazing"}', '{"all-ages"}', 'Free', 'Jan Juc / anywhere', 0, '{"any"}', '< 1hr', 'Venus, Jupiter, Saturn and Mars are all visible to the naked eye from Jan Juc on clear nights — no telescope needed. Jupiter is so bright it''s unmissable. Saturn looks slightly cream-yellow. Venus is the brilliant ''evening star'' or ''morning star'' depending on the season. Use the free Stellarium app (point your phone at the sky) to identify everything you can see. On a good night with dark-adapted eyes you can also see the Magellanic Clouds — two small galaxies visible only from the southern hemisphere.', 'https://stellarium-web.org', 5, 'Stellarium app is free and brilliant for kids. Point phone at sky to identify planets & constellations', '{"clear-sky","low-wind"}', -38.3655, 144.2978, 'night', 'Research', true)
